/**
 * Pre-flight check for `npm run build:static`.
 *
 * A static bundle's only data source is `public/traces/*.json`, and those are
 * gitignored — they are generated by `backend/scripts/export_traces.py`, which
 * needs the backend's dependencies and, by default, the 124M checkpoint. So the
 * most likely way to hit this build is to skip that step, and the result is a
 * deploy where every trace button 404s and the app looks broken with no
 * explanation.
 *
 * Checking here turns that into an actionable error message instead.
 *
 * Also verifies the files parse and carry the step list the replay hook expects,
 * because a truncated file (an interrupted export) is worse than a missing one:
 * it loads, then fails mid-render.
 */

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

const TRACES_DIR = join(process.cwd(), 'public', 'traces');

const REQUIRED_TOP_LEVEL = ['name', 'model_id', 'prompt', 'params', 'steps'];

let failed = false;

function fail(message) {
  console.error(`  FAIL ${message}`);
  failed = true;
}

let entries;
try {
  entries = readdirSync(TRACES_DIR).filter((f) => f.endsWith('.json'));
} catch {
  console.error(`no traces directory at ${TRACES_DIR}`);
  console.error('');
  console.error('A static build has no backend, so exported traces are its only data.');
  console.error('Generate them first:');
  console.error('');
  console.error('  cd ../backend');
  console.error('  pip install -r requirements.txt');
  console.error('  python -m scripts.export_traces');
  console.error('');
  process.exit(1);
}

if (entries.length === 0) {
  console.error(`no traces found in ${TRACES_DIR}`);
  console.error('Generate them with: cd ../backend && python -m scripts.export_traces');
  process.exit(1);
}

console.log(`checking ${entries.length} trace bundle(s)`);

let totalBytes = 0;

for (const file of entries) {
  const path = join(TRACES_DIR, file);
  const bytes = statSync(path).size;
  totalBytes += bytes;
  const mb = (bytes / 1024 / 1024).toFixed(2);

  let doc;
  try {
    doc = JSON.parse(readFileSync(path, 'utf8'));
  } catch (err) {
    fail(`${file} is not valid JSON (${err.message}) — re-run export_traces.py`);
    continue;
  }

  for (const key of REQUIRED_TOP_LEVEL) {
    if (!(key in doc)) fail(`${file} is missing "${key}"`);
  }

  if (!Array.isArray(doc.steps)) {
    fail(`${file}: "steps" is not an array`);
    continue;
  }
  if (doc.steps.length === 0) {
    fail(`${file}: "steps" is empty, so replay would show nothing`);
    continue;
  }

  // Each step must carry the fields the replay hook and store read directly.
  // Checking one step is enough: they are serialized by the same code path.
  const first = doc.steps[0];
  for (const key of ['type', 'request_id', 'step', 'token_id', 'piece', 'token_ids', 'text', 'finished']) {
    if (!(key in first)) fail(`${file}: steps[0] is missing "${key}"`);
  }

  // `trace: false` exports are legal but useless to a visualizer, so warn.
  const withTrace = doc.steps.filter((s) => s.trace !== null && s.trace !== undefined).length;
  if (withTrace === 0) {
    fail(`${file}: no step carries a trace — re-run export_traces.py without --no-traces`);
  }

  if (!failed) {
    console.log(
      `  ok   ${file.padEnd(14)} ${mb.padStart(6)} MB  ${doc.steps.length} steps, ${withTrace} with traces, T=${doc.steps[0].trace?.input_token_ids?.length ?? '?'}`,
    );
  }
}

console.log(`  total ${(totalBytes / 1024 / 1024).toFixed(2)} MB of trace data will be served as static files`);

if (failed) {
  console.error('');
  console.error('Re-run: cd ../backend && python -m scripts.export_traces');
  process.exit(1);
}

console.log('traces OK');
